// lib/skuFormat.js
// Product SKUs are generated by the system now, so nobody has to invent one:
//
//   <vendor><name><sequence>      e.g.  VND001-TOM-001
//
//   VND001  → the vendor's code with dashes/spaces removed (VND-001)
//   TOM     → the first three letters of the product name (Tomatoes)
//   001     → the next free number for that vendor + name token
//
// The sequence is tracked per vendor and per name token, so importing
// "Tomatoes" twice gives TOM-001 then TOM-002 instead of a duplicate-SKU error.
const pad = (n, width = 3) => String(n).padStart(width, '0')

export function vendorToken(code) {
  const clean = String(code || '')
    .toUpperCase()
    .replace(/[^A-Z0-9]/g, '')
  return clean ? clean.slice(0, 10) : 'VND'
}

export function nameToken(name) {
  const clean = String(name || '')
    .toUpperCase()
    .replace(/[^A-Z0-9]/g, '')
  return clean ? clean.slice(0, 3).padEnd(3, 'X') : 'ITM'
}

export function buildSku(vendorCode, name, seq) {
  return `${vendorToken(vendorCode)}-${nameToken(name)}-${pad(seq)}`
}

// Reads the highest sequence already used per "<vendor>-<token>" prefix, so a
// batch continues where the existing catalog stopped.
function highWaterMark(vendorCode, existingSkus) {
  const vTok = vendorToken(vendorCode)
  const marks = new Map()
  for (const raw of existingSkus || []) {
    const sku = String(raw || '').toUpperCase()
    const parts = sku.split('-')
    if (parts.length !== 3 || parts[0] !== vTok) continue
    const seq = Number(parts[2])
    if (!Number.isFinite(seq)) continue
    const prefix = `${parts[0]}-${parts[1]}`
    marks.set(prefix, Math.max(marks.get(prefix) || 0, seq))
  }
  return marks
}

// Generates one collision-free SKU per name, in the same order as `names`.
export function reserveSkus({ vendorCode, names, existingSkus = [] }) {
  const taken = new Set((existingSkus || []).map((s) => String(s || '').toUpperCase()))
  const marks = highWaterMark(vendorCode, taken)
  const vTok = vendorToken(vendorCode)

  return (names || []).map((name) => {
    const token = nameToken(name)
    const prefix = `${vTok}-${token}`
    let seq = (marks.get(prefix) || 0) + 1
    let sku = buildSku(vendorCode, name, seq)
    while (taken.has(sku)) {
      seq += 1
      sku = buildSku(vendorCode, name, seq)
    }
    marks.set(prefix, seq)
    taken.add(sku)
    return sku
  })
}
